import Link from "next/link";
import type { ReactNode } from "react";
import { cx } from "@/components/ui/_internal/cx";
import { IconArrowLeft } from "@/components/ui/Icon/Icon";
import styles from "./AuthCard.module.css";

/**
 * The auth inversion: a solid card on its own deep backdrop, for sign-in,
 * sign-up, password and MFA screens. Three fixed layers (base, floor shade
 * and sky light) are read from tokens (--auth-background, --auth-floor,
 * --auth-sky), so a theme restyles the backdrop without touching this file.
 * `contained` fills a fixed-height parent instead of the viewport (docs).
 */
export type AuthLayoutProps = {
  children: ReactNode;
  /** A bar across the top of the page: your brand mark at the left, a help link at the right. */
  header?: ReactNode;
  /** A strip at the foot of the page: a security note, legal links. */
  footer?: ReactNode;
  /** Fill a fixed-height parent instead of the viewport (docs previews). */
  contained?: boolean;
};

export function AuthLayout({ children, header, footer, contained }: AuthLayoutProps) {
  return (
    <div className={cx(styles.page, contained && styles.contained)}>
      <div className={styles.bgBase} aria-hidden="true" />
      <div className={styles.bgFloor} aria-hidden="true" />
      <div className={styles.bgSky} aria-hidden="true" />
      {header ? <header className={styles.header}>{header}</header> : null}
      {contained ? (
        <div className={styles.column}>{children}</div>
      ) : (
        <main id="main" className={styles.column}>
          {children}
        </main>
      )}
      {footer ? <footer className={styles.footer}>{footer}</footer> : null}
    </div>
  );
}

export type AuthCardProps = {
  title: ReactNode;
  subtitle?: ReactNode;
  /** Your logo or wordmark, centred above the title. */
  logo?: ReactNode;
  /** Icon tile above the title (MFA screens). */
  icon?: ReactNode;
  /** A small tag beside nothing else: "Admin", "Staging". Sits above the title on one line with it. */
  badge?: ReactNode;
  children: ReactNode;
  /** A strip under the card body: a trust line, a terms link. */
  footer?: ReactNode;
  /** sm 440 (sign-in, MFA), md 520 (set password), lg 720 (onboarding). */
  width?: "sm" | "md" | "lg";
  /** A way out, under the form: "Back to sign in". */
  back?: { href: string; label: string };
};

export function AuthCard({ title, subtitle, logo, icon, badge, children, footer, width = "sm", back }: AuthCardProps) {
  return (
    <section className={cx(styles.card, styles[width])} data-surface="solid">
      <div className={styles.body}>
        {logo ? <div className={styles.logo}>{logo}</div> : null}
        <header className={styles.heading}>
          {icon ? (
            <span className={styles.iconTile} aria-hidden="true">
              {icon}
            </span>
          ) : null}
          <h1 className={styles.title}>
            {title}
            {badge ? <span className={styles.badge}>{badge}</span> : null}
          </h1>
          {subtitle ? <p className={styles.subtitle}>{subtitle}</p> : null}
        </header>
        {children}
        {back ? (
          <div className={styles.backRow}>
            <Link href={back.href} className={styles.back}>
              <IconArrowLeft size={14} />
              {back.label}
            </Link>
          </div>
        ) : null}
      </div>
      {footer ? <div className={styles.strip}>{footer}</div> : null}
    </section>
  );
}

.page {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  min-height: 100dvh;
}

.bgBase,
.bgFloor,
.bgSky {
  position: fixed;
  inset: 0;
  pointer-events: none;
}

.bgBase {
  background: var(--auth-background);
}

.bgFloor {
  background: var(--auth-floor);
}

.bgSky {
  background: var(--auth-sky);
}

.column {
  position: relative;
  z-index: 1;
  display: flex;
  flex: 1;
  align-items: center;
  justify-content: center;
  width: 100%;
  padding: 24px 16px 0;
}

.page > footer {
  position: relative;
  z-index: 1;
}

/* Docs preview: fill a fixed-height parent; the layers stay inside it. */
.contained {
  min-height: 100%;
  height: 100%;
  overflow: hidden;
}

.contained .bgBase,
.contained .bgFloor,
.contained .bgSky {
  position: absolute;
}

/* The brand bar and the footer strip sit on the field, in inverse ink, so
   the card in the middle is the only solid object on the page. */
.header {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  width: 100%;
  padding: 18px 24px;
  color: var(--auth-ink, var(--ink-inverse));
}

.footer {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  width: 100%;
  margin-top: 40px;
  padding: 16px 24px 20px;
  font-size: var(--text-caption);
  color: var(--auth-ink-muted, rgba(255, 255, 255, 0.78));
}

@media (min-width: 640px) {
  .column {
    padding: 24px 32px 0;
  }
}

/* An object on the deep field: solid, a contact shadow and a soft fall
   (--shadow-auth-card). */
.card {
  width: 100%;
  overflow: hidden;
  border-radius: var(--r-xl);
  background: var(--surface-solid);
  box-shadow: var(--shadow-auth-card);
}

.sm {
  max-width: 440px;
}

.md {
  max-width: 520px;
}

.lg {
  max-width: 720px;
}

.body {
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 36px 36px 30px;
}

@media (max-width: 480px) {
  .body {
    padding: 28px 22px 24px;
  }
}

.logo {
  display: flex;
  justify-content: center;
  margin-bottom: 10px;
}

.logo > span {
  align-items: center;
}

.heading {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
  margin-bottom: 10px;
  text-align: center;
}

.iconTile {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 48px;
  height: 48px;
  margin-bottom: 8px;
  border-radius: var(--r-lg);
  background: var(--brand-gradient-soft);
  box-shadow: inset 0 0 0 1px var(--line-brand);
  color: var(--ink-brand);
}

/* Inline with the title, never stacked over it. */
.badge {
  display: inline-flex;
  align-items: center;
  margin-left: 10px;
  padding: 2px 8px;
  vertical-align: 4px;
  border-radius: var(--r-full);
  background: var(--brand-fill);
  box-shadow: inset 0 0 0 1px var(--brand-line);
  font-family: var(--font-body);
  font-size: var(--text-micro);
  font-weight: 700;
  letter-spacing: 0.04em;
  color: var(--brand-ink);
}

.title {
  font-family: var(--font-display);
  font-size: var(--text-auth-title);
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: var(--heading-tracking, var(--tracking-display));
  text-transform: var(--heading-case, none);
  text-wrap: balance;
  color: var(--ink-heading);
}

.subtitle {
  max-width: 42ch;
  font-size: 13.5px;
  line-height: 1.55;
  color: var(--ink-muted);
}

.backRow {
  margin-top: 10px;
  padding-top: 16px;
  border-top: 1px solid var(--line-soft);
}

.back {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: var(--text-caption);
  font-weight: 700;
  color: var(--ink-brand);
  text-decoration: none;
}

.back:hover {
  color: var(--brand-deep);
  text-decoration: underline;
  text-underline-offset: 3px;
}

.back:focus-visible {
  outline: 2px solid var(--ink-heading);
  outline-offset: 2px;
}

.strip {
  padding: 13px 28px;
  background: var(--surface-sunken);
  border-top: 1px solid var(--line-soft);
  text-align: center;
}

.trust {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 11.5px;
  color: var(--ink-muted);
}
